import React, { useEffect, useState } from "react";
import UserProfileCard from "./UserProfileCard";
import AchievementsPanel from "./AchievementsPanel";
import "./dashboard.css";
const API = process.env.REACT_APP_API || "http://localhost:4000";

function StatCard({ value, label }) {
  return (
    <div className="stat-card">
      <div className="stat-value">{value ?? "—"}</div>
      <div className="stat-label">{label}</div>
    </div>
  );
}

export default function AdminDashboard({ token, setMsg, reports }) {
  const [admin, setAdmin] = useState(null);
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [mostActive, setMostActive] = useState(null);
  const [loading, setLoading] = useState({ profile: false, data: false });
  const [activeSection, setActiveSection] = useState(null); // "ngos", "events", "stats"

  // fetch profile
  useEffect(() => {
    if (!token) return;
    (async () => {
      setLoading((s) => ({ ...s, profile: true }));
      try {
        const res = await fetch(`${API}/api/auth/me`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json?.message || "Failed to load profile");
        setAdmin(json.user || null);
      } catch (err) {
        console.error(err);
        setMsg(err.message || "Error loading profile");
      } finally {
        setLoading((s) => ({ ...s, profile: false }));
      }
    })();
  }, [token, setMsg]);

  // common loader
  const loadData = async (endpoint, setter, field = null, section = null) => {
    if (!token) return setMsg("Login as admin first");
    setLoading((s) => ({ ...s, data: true }));
    try {
      const res = await fetch(`${API}${endpoint}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.message || "Failed to load");
      setter(field ? json[field] || [] : json);
      setActiveSection(section); // show only this section
      setMsg("");
    } catch (err) {
      console.error(err);
      setMsg(err.message || "Failed to load");
    } finally {
      setLoading((s) => ({ ...s, data: false }));
    }
  };

  const deleteNgo = async (id) => {
    if (!token) return setMsg("Login as admin first");
    if (!window.confirm("Are you sure you want to remove this NGO?")) return;
    try {
      const res = await fetch(`${API}/api/actions/remove-ngo/${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json?.message || "Failed to delete NGO");
      setNgos((prev) => prev?.filter((n) => n.id !== id) || []);
      setMsg("NGO removed successfully");
    } catch (err) {
      console.error(err);
      setMsg(err.message || "Failed to delete NGO");
    }
  };

  const donationsSum = reports?.donations
    ? reports.donations.reduce((s, d) => s + parseFloat(d.amount || 0), 0)
    : "-";

  return (
    <div className="dashboard-wrap">
      <div className="dashboard-container">

        {/* Top row: Profile + Achievements + General Info + Quick Links */}
        <div className="top-row">
          <div className="left-panel">
            <div className="profile-box">
              {loading.profile ? <div className="loading">Loading profile…</div> : <UserProfileCard data={admin} />}
            </div>
            <AchievementsPanel token={token} me={{ points: reports?.adminPoints || 0 }} setMsg={setMsg} />
          </div>

          <div className="center-panel">
            <div className="general-info">
              <StatCard value={reports?.adminPoints ?? 0} label="Total Points" />
              <StatCard value={reports?.totalUsers || 0} label="Total Users" />
              <StatCard value={reports?.totalEvents || 0} label="Total Events" />
              <StatCard value={reports?.volunteers?.length || 0} label="Volunteers" />
            </div>
          </div>

          <div className="right-panel">
            <div className="quick-actions">
              <h4>Quick Actions</h4>
              <button onClick={() => loadData("/api/actions/most-active-ngo", setMostActive, "top", "mostActive")}>
                Load Most Active NGO
              </button>
              {mostActive && (
                <div className="most-active-info">
                  <strong>{mostActive.name}</strong>
                  <div className="muted">Activity Score: {mostActive.activity_score}</div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Bottom row: 3 major buttons */}
        <div className="bottom-row">
          <button onClick={() => loadData("/api/actions/ngos", setNgos, "ngos", "ngos")}>View NGOs</button>
          <button onClick={() => loadData("/api/actions/registered-events", setEvents, "events", "events")}>View Events</button>
          <button onClick={() => loadData("/api/actions/event-stats", setEventStats, "events", "stats")}>View Stats</button>
        </div>

        {/* Dynamic section: show only active */}
        <div className="dynamic-section">
          {activeSection === "ngos" && ngos && (
            <>
              <h4>Registered NGOs</h4>
              <div className="list-grid">
                {ngos.length ? ngos.map((n) => (
                  <div key={n.id} className="list-item spaced">
                    <div>
                      <div className="list-title">{n.name}</div>
                      <div className="muted small">{n.email}</div>
                    </div>
                    <div>
                      <button className="danger" onClick={() => deleteNgo(n.id)}>Remove</button>
                    </div>
                  </div>
                )) : <div className="muted">No NGOs registered.</div>}
              </div>
            </>
          )}

          {activeSection === "events" && events && (
            <>
              <h4>Registered Events</h4>
              <div className="list-grid">
                {events.length ? events.map((e) => (
                  <div key={e.id} className="list-item">
                    <div className="list-title">{e.title}</div>
                    <div className="muted small">{e.date}</div>
                  </div>
                )) : <div className="muted">No events registered.</div>}
              </div>
            </>
          )}

          {activeSection === "stats" && eventStats && (
            <>
              <h4>Event Statistics</h4>
              <div className="list-grid">
                {eventStats.length ? eventStats.map((ev) => (
                  <div key={ev.id} className="list-item horizontal">
                    <img src={ev.image_url || "/placeholder-120x80.png"} alt="" className="thumb" />
                    <div>
                      <div className="list-title">{ev.title}</div>
                      <div className="muted small">Volunteers: {ev.volunteers_count} — Donations: ₹{ev.donations_sum}</div>
                    </div>
                  </div>
                )) : <div className="muted">No event statistics loaded.</div>}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
